# 30_setup_fig6.R: create the working directories for the eutrophication analysis (Figure 6) on the shared EPA lake pool (principal) and the full site pools (sensitivity).
# The Figure 6 and supplementary scripts of the earlier analysis (../fig6) are copied unchanged except that (i) Polish phytoplankton is removed, (ii) evaluated orders are harmonised with Figures 3 and 5
# (sharing probability >= 0.10: macroinvertebrates 2-12, zooplankton 2-5), (iii) labels use 'taxa'. Run order inside each directory is listed in run_fig6.sh.
src <- "../fig6"; POOLS <- readRDS("out/pools.rds"); labs <- c(BM = "EPA macroinvertebrates", ZP = "EPA zooplankton")
for (pool in c("shared", "full")) { dir <- paste0("fig6_", pool); dir.create(file.path(dir, "out"), recursive = TRUE, showWarnings = FALSE); dir.create(file.path(dir, "repl"), FALSE)
  D <- lapply(c("BM", "ZP"), function(g) list(code = g, label = labs[[g]], x = POOLS[[pool]][[g]]$x, env = POOLS[[pool]][[g]]$env, n_raw = nrow(POOLS[[pool]][[g]]$x), n_dup = 0L, n_dropped = 0L)); names(D) <- c("BM", "ZP"); saveRDS(D, file.path(dir, "out", "prepared.rds"))
  for (f in c("lib6.R", "02_orders.R", "03_validate.R", "03b_penalty.R", "04_fit.R", "04b_fit_lowpenalty.R", "05_tables.R", "06_surface_tables.R", "07_figure6.R")) { s <- readLines(file.path(src, f)); s <- gsub("BM = c(2, 3, 4, 5, 6, 8, 10), ZP = c(2, 3, 4, 5, 6), PP = c(2, 3, 4, 5)", "BM = c(2, 3, 4, 5, 6, 8, 10, 12), ZP = c(2, 3, 4, 5)", s, fixed = TRUE); s <- gsub(', PP = "Phytoplankton"', "", s, fixed = TRUE); s <- gsub(', Phytoplankton = pal[["sage"]]', "", s, fixed = TRUE); s <- gsub("print(names(res$PP)); str(res$PP, max.level = 1, give.attr = FALSE); print(head(as.data.frame(res$PP), 15))", "print(head(as.data.frame(res$BM), 5))", s, fixed = TRUE); s <- gsub("P(shared species)", "P(shared taxa)", s, fixed = TRUE); s <- gsub('PA <- (pA1 | pA2) + plot_layout(widths = c(1.35, 1), tag_level = "new"); fig <- wrap_plots(PA, pB, mkC(k), pD, ncol = 1, heights = c(1.0, 2.0, 2.3, 2.3)) + plot_annotation(tag_levels = list(c("A", "B", "C", "D"), "a"), tag_sep = "") &', 'PA <- ((pA1 + labs(tag = "A")) | (pA2 + labs(tag = "B"))) + plot_layout(widths = c(1.35, 1)); fig <- wrap_plots(PA, pB + labs(tag = "C"), mkC(k) + labs(tag = "D"), pD + labs(tag = "E"), ncol = 1, heights = c(1.0, 2.0, 2.3, 2.3)) &', s, fixed = TRUE); writeLines(s, file.path(dir, f)) }
  for (f in c("lib_repl.R", "10_fit.R", "11_surfaces.R", "12_tables.R", "13_figures.R", "14_freesign.R")) { s <- readLines(file.path(src, "repl", f)); s <- gsub("BM = c(2, 3, 4, 5, 6, 8, 10), ZP = c(2, 3, 4, 5, 6), PP = c(2, 3, 4, 5)", "BM = c(2, 3, 4, 5, 6, 8, 10, 12), ZP = c(2, 3, 4, 5)", s, fixed = TRUE); s <- gsub(', PP = "Phytoplankton"', "", s, fixed = TRUE); s <- gsub(', Phytoplankton = pal[["sage"]]', "", s, fixed = TRUE); writeLines(s, file.path(dir, "repl", f)) }
  writeLines(c("#!/bin/sh", "# Run inside this directory with ZG_LIB6 set to the zetaGDUM f7e115f library", "Rscript 02_orders.R", "Rscript 03_validate.R", "Rscript 03b_penalty.R", "Rscript 04_fit.R", "Rscript 04b_fit_lowpenalty.R", "Rscript 05_tables.R", "Rscript 06_surface_tables.R", "Rscript 07_figure6.R", "Rscript repl/10_fit.R", "Rscript repl/11_surfaces.R", "Rscript repl/12_tables.R", "Rscript repl/13_figures.R", "Rscript repl/14_freesign.R"), file.path(dir, "run_fig6.sh")) }
